{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.uc_logic_pv_check AS WITH uc_base AS ( SELECT UPPER(TRIM(\"PO Code\")) AS PO_CODE_STD, UPPER( TRIM( REPLACE( REPLACE( REPLACE(\"Item SkuCode\", CHR(13), \'\'), CHR(10), \'\'), CHR(9), \'\') ) ) AS SKU_STD, UPPER(TRIM(\"Vendor Code\")) AS VENDOR_CODE, UPPER(TRIM(\"Vendor Name\")) AS VENDOR_NAME, TRY_TO_TIMESTAMP_NTZ(CREATED) AS UC_CREATED_TS, TRY_TO_TIMESTAMP_NTZ(UPDATED) AS UC_UPDATED_TS, TRY_TO_DATE(\"Delivery Date\") AS UC_DELIVERY_DATE, TO_NUMBER(\"Order Quantity\") AS UC_ORDER_QTY, TO_NUMBER(\"Pending Quantity\") AS UC_PENDING_QTY, TO_NUMBER(\"Recieved Quantity\") AS UC_RECEIVED_QTY, TO_NUMBER(\"Rejected Quantity\") AS UC_REJECTED_QTY, UPPER(TRIM(\"Purchase Order Status\")) AS UC_PO_STATUS, _AIRBYTE_EMITTED_AT FROM snitch_db.maplemonk.uc_final_get_purchase_orders WHERE TRY_TO_TIMESTAMP_NTZ(CREATED) >= \'2025-12-01\' AND \"PO Code\" NOT LIKE \'%WR%\' ), uc_dedup AS ( SELECT * FROM ( SELECT u.*, ROW_NUMBER() OVER ( PARTITION BY PO_CODE_STD, SKU_STD, VENDOR_CODE ORDER BY UC_UPDATED_TS DESC NULLS LAST, _AIRBYTE_EMITTED_AT DESC NULLS LAST ) AS rn FROM uc_base u ) WHERE rn = 1 ), uc_final AS ( SELECT PO_CODE_STD, SKU_STD, MAX(VENDOR_CODE) AS VENDOR_CODE, MAX(VENDOR_NAME) AS VENDOR_NAME, MIN(UC_CREATED_TS) AS UC_CREATED_TS, MAX(UC_UPDATED_TS) AS UC_UPDATED_TS, MAX(UC_DELIVERY_DATE) AS UC_DELIVERY_DATE, MAX(UC_PO_STATUS) AS UC_PO_STATUS, SUM(COALESCE(UC_ORDER_QTY,0)) AS UC_ORDER_QTY, SUM(COALESCE(UC_PENDING_QTY,0)) AS UC_PENDING_QTY, SUM(COALESCE(UC_RECEIVED_QTY,0)) AS UC_RECEIVED_QTY, SUM(COALESCE(UC_REJECTED_QTY,0)) AS UC_REJECTED_QTY, COUNT(*) AS UC_RAW_LINE_COUNT FROM uc_dedup where VENDOR_NAME NOT ILIKE \'%SNITCH%\' AND VENDOR_NAME NOT LIKE \'%STORE%\' AND VENDOR_NAME NOT IN (\'HIGHSTREET-RAJPURROAD\',\'SARATH CITY HYDERABAD\',\'SAPL GUJARAT\') AND VENDOR_NAME NOT LIKE \'%WBC%\' GROUP BY 1,2 ), logic_base AS ( SELECT UPPER(TRIM(l.GRN_PREFIX)) || \'-\' || REGEXP_REPLACE(TRIM(TO_VARCHAR(l.GRN_NUMBER)), \'\\.0+$\', \'\') AS PO_CODE_STD, UPPER( TRIM( REPLACE( REPLACE( REPLACE(l.SKU, CHR(13), \'\'), CHR(10), \'\'), CHR(9), \'\') ) ) AS SKU_RAW_STD, COALESCE( CASE WHEN REGEXP_COUNT(UPPER(TRIM(l.SKU)), \'-\') >= 2 AND REGEXP_LIKE(UPPER(TRIM(l.SKU)), \'^[A-Z0-9].*-.*-.*\') THEN UPPER( TRIM( REPLACE(REPLACE(REPLACE(l.SKU, CHR(13), \'\'), CHR(10), \'\'), CHR(9), \'\') ) ) ELSE NULL END, UPPER(TRIM(m.SKU)), UPPER( TRIM( REPLACE(REPLACE(REPLACE(l.SKU, CHR(13), \'\'), CHR(10), \'\'), CHR(9), \'\') ) ) ) AS SKU_STD, TO_VARCHAR(l.ITEMCODE) AS ITEMCODE_EAN, UPPER(TRIM(l.TO_PARTY)) AS TO_PARTY, UPPER(TRIM(l.FROM_PARTY)) AS FROM_PARTY, BILL_DATE AS BILL_DATE, VOUCH_DATE AS VOUCH_DATE, l.ITEM_QUANTITY AS LOGIC_ITEM_QTY, l.QTY_EXCESS AS LOGIC_QTY_EXCESS, l.QTY_REJECTED AS LOGIC_QTY_REJECTED, l.QTY_SCANNED AS LOGIC_QTY_SCANNED, l.NET_AMOUNT AS LOGIC_NET_AMOUNT, l.GROSS_AMOUNT AS LOGIC_GROSS_AMOUNT, l.TOTAL_TAX AS LOGIC_TOTAL_TAX, l.UNIQUEKEY, l.BILL_NO, l.VOUCH_NO, l.LOT_NUMBER, l.PUR_TXN_CODE FROM snitch_db.maplemonk.logic_purchase_voucher l LEFT JOIN snitch_db.maplemonk.ean_to_sku_mapping m ON TO_VARCHAR(l.ITEMCODE) = m.EAN WHERE l.TO_PARTY NOT IN (\'SNITCH - HO\',\'SNITCH - WH - B2B\',\'SURAT-VRMALL\') ), logic_filtered AS ( SELECT * FROM logic_base WHERE BILL_DATE >= \'2025-12-01\' ), logic_dedup AS ( SELECT * FROM ( SELECT l.*, ROW_NUMBER() OVER ( PARTITION BY PO_CODE_STD, SKU_STD, COALESCE(LOT_NUMBER,\'\'), COALESCE(PUR_TXN_CODE,\'\') ORDER BY BILL_DATE DESC NULLS LAST, VOUCH_DATE DESC NULLS LAST, UNIQUEKEY DESC ) AS rn FROM logic_filtered l ) WHERE rn = 1 ), logic_final AS ( SELECT PO_CODE_STD, SKU_STD, MAX(TO_PARTY) AS TO_PARTY, MAX(FROM_PARTY) AS FROM_PARTY, MIN(BILL_DATE) AS LOGIC_BILL_DATE, MAX(VOUCH_DATE) AS LOGIC_VOUCH_DATE, SUM(COALESCE(LOGIC_ITEM_QTY,0)) AS LOGIC_ITEM_QTY, SUM(COALESCE(LOGIC_QTY_EXCESS,0)) AS LOGIC_QTY_EXCESS, SUM(COALESCE(LOGIC_QTY_REJECTED,0)) AS LOGIC_QTY_REJECTED, SUM(COALESCE(LOGIC_QTY_SCANNED,0)) AS LOGIC_QTY_SCANNED, MAX(LOGIC_NET_AMOUNT) AS LOGIC_NET_AMOUNT, MAX(LOGIC_GROSS_AMOUNT) AS LOGIC_GROSS_AMOUNT, MAX(LOGIC_TOTAL_TAX) AS LOGIC_TOTAL_TAX, COUNT(*) AS LOGIC_RAW_LINE_COUNT FROM logic_dedup GROUP BY 1,2 ) SELECT COALESCE(u.PO_CODE_STD, l.PO_CODE_STD) AS PO_CODE, COALESCE(u.SKU_STD, l.SKU_STD) AS SKU, u.VENDOR_CODE, u.VENDOR_NAME, u.UC_CREATED_TS, u.UC_UPDATED_TS, u.UC_DELIVERY_DATE, u.UC_PO_STATUS, u.UC_ORDER_QTY, u.UC_PENDING_QTY, u.UC_RECEIVED_QTY, u.UC_REJECTED_QTY, u.UC_RAW_LINE_COUNT, l.TO_PARTY, l.FROM_PARTY, l.LOGIC_BILL_DATE, l.LOGIC_VOUCH_DATE, l.LOGIC_ITEM_QTY, l.LOGIC_QTY_EXCESS, l.LOGIC_QTY_REJECTED, l.LOGIC_QTY_SCANNED, l.LOGIC_NET_AMOUNT, l.LOGIC_GROSS_AMOUNT, l.LOGIC_TOTAL_TAX, l.LOGIC_RAW_LINE_COUNT, CASE WHEN u.PO_CODE_STD IS NOT NULL AND l.PO_CODE_STD IS NOT NULL THEN \'PRESENT_IN_BOTH\' WHEN u.PO_CODE_STD IS NOT NULL AND l.PO_CODE_STD IS NULL THEN \'MISSING_IN_LOGIC\' WHEN u.PO_CODE_STD IS NULL AND l.PO_CODE_STD IS NOT NULL THEN \'MISSING_IN_UC\' ELSE \'UNKNOWN\' END AS PRESENCE_STATUS, (COALESCE(u.UC_ORDER_QTY,0) - COALESCE(l.LOGIC_ITEM_QTY,0)) AS DIFF_ORDER_QTY, (COALESCE(u.UC_RECEIVED_QTY,0) - COALESCE(l.LOGIC_QTY_SCANNED,0)) AS DIFF_RECEIVED_VS_SCANNED, CASE WHEN COALESCE(u.UC_ORDER_QTY,0) = COALESCE(l.LOGIC_ITEM_QTY,0) THEN 1 ELSE 0 END AS IS_ORDER_QTY_MATCH FROM uc_final u FULL OUTER JOIN logic_final l ON u.PO_CODE_STD = l.PO_CODE_STD AND u.SKU_STD = l.SKU_STD ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            